async function renderMovie(download=true){let rec,stream,ctx,audio,v,renderTimer,disabledStates,recordingError;try{if(busy)throw Error('请等待当前操作结束');if(document.hidden)throw Error('请将页面切换到前台后再导出');stopTimelinePreview();clearExportResult();const p=structuredClone(current());if(!window.MediaRecorder||!HTMLCanvasElement.prototype.captureStream)throw Error('浏览器不支持导出，请使用桌面 Chrome');busy=true;cancelled=false;$('preview').pause();$('cancel').hidden=false;disabledStates=new Map([...document.querySelectorAll('button,input,select,textarea')].map(e=>[e,e.disabled]));disabledStates.forEach((disabled,e)=>e.disabled=true);$('cancel').disabled=false;const [w,h]=$('ratio').value==='16:9'?[1280,720]:$('ratio').value==='1:1'?[720,720]:[720,1280];const canvas=$('canvas');canvas.width=w;canvas.height=h;ctx=canvas.getContext('2d');audio=new AudioContext();await audio.resume();const destination=audio.createMediaStreamDestination();v=document.createElement('video');v.playsInline=true;v.preload='auto';v.className='render-source';$('preview').hidden=true;$('previewcaption').hidden=true;canvas.hidden=false;document.querySelector('.screen').append(v);const source=audio.createMediaElementSource(v);source.connect(destination);stream=canvas.captureStream(30);destination.stream.getAudioTracks().forEach(t=>stream.addTrack(t));rec=createMP4Recorder(stream);const mime=rec.mimeType;const chunks=[];rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};const done=new Promise((resolve,reject)=>{rec.onstop=resolve;rec.onerror=e=>{recordingError=e.error||Error('编码失败');resolve()}});let clip,elapsed=0;const total=p.clips.reduce((t,c)=>t+c.end-c.start,0);function frame(){ctx.fillStyle='#000';ctx.fillRect(0,0,w,h);if(v.readyState>=2){const visual=visualEffect(clip?.effect,Math.max(0,v.currentTime-(clip?.start||0)),(clip?.end||1)-(clip?.start||0));const scale=Math.min(w/v.videoWidth,h/v.videoHeight)*visual.scale;ctx.globalAlpha=visual.alpha;ctx.drawImage(v,(w-v.videoWidth*scale)/2,(h-v.videoHeight*scale)/2,v.videoWidth*scale,v.videoHeight*scale);ctx.globalAlpha=1}if(clip?.caption){const layout=captionLayout(clip.caption,w,h,(text,size)=>{ctx.font=`bold ${size}px sans-serif`;return ctx.measureText(text).width});ctx.font=`bold ${layout.size}px sans-serif`;ctx.textAlign='center';const top=layout.bottom-layout.lines.length*layout.lineHeight;ctx.fillStyle='rgba(0,0,0,.7)';ctx.fillRect(0,top-layout.size*.5,w,layout.lines.length*layout.lineHeight+layout.size);ctx.fillStyle='white';layout.lines.forEach((line,i)=>ctx.fillText(line,w/2,top+(i+1)*layout.lineHeight));} }frame();renderTimer=setInterval(frame,1000/30);for(const c of p.clips){if(cancelled)throw Error('已取消');clip=c;v.src=assets[c.asset].url;v.load();await waitEvent(v,'loadeddata');if(c.start>0){const seek=waitEvent(v,'seeked');v.currentTime=c.start;await seek}frame();if(rec.state==='inactive')rec.start();else if(rec.state==='paused')rec.resume();await v.play();status('正在导出，请保持页面在前台…');await new Promise((resolve,reject)=>{const start=performance.now();const timer=setInterval(()=>{if(recordingError){clearInterval(timer);reject(recordingError);return}if(cancelled||document.hidden){clearInterval(timer);reject(Error(cancelled?'已取消':'页面已进入后台，请保持页面前台后重新导出'));return}const t=Math.min(c.end-c.start,Math.max(0,v.currentTime-c.start));$('progress').value=100*(elapsed+t)/total;if(v.currentTime>=c.end-.03||v.ended){clearInterval(timer);resolve()}else if(performance.now()-start>(c.end-c.start+20)*1000){clearInterval(timer);reject(Error('播放停滞，导出已停止'))}},25)});v.pause();rec.pause();elapsed+=c.end-c.start}rec.stop();await done;if(recordingError)throw recordingError;const blob=new Blob(chunks,{type:'video/mp4'});await verifyMP4(blob);if(resultURL)URL.revokeObjectURL(resultURL);resultURL=URL.createObjectURL(blob);$('result-video').src=resultURL;$('result-download').href=resultURL;$('export-result').hidden=false;$('preview').src=resultURL;$('preview').controls=true;$('preview-label').textContent=`再创作成片 · ${total.toFixed(1)} 秒 · MP4`;$('preview-state').textContent='当前播放器是重新剪辑后的成片，可以拖动进度条检查。';if(download)save('clippilot.mp4',blob,'video/mp4');$('progress').value=100;status(download?'再创作 MP4 已生成并开始下载，包含时间线剪辑、字幕、效果及原音轨。':'再创作 MP4 已生成。上方可播放完整成片，满意后点击下载 MP4。')}catch(e){if(rec&&rec.state!=='inactive')rec.stop();status(cancelled?'导出已取消，未生成文件':'导出失败：'+e.message)}finally{clearInterval(renderTimer);v?.pause();v?.remove();$('canvas').hidden=true;$('preview').hidden=false;$('previewcaption').hidden=false;stream?.getTracks().forEach(t=>t.stop());await audio?.close();busy=false;$('cancel').hidden=true;disabledStates?.forEach((disabled,e)=>e.disabled=disabled)}};
$('export').onclick=()=>renderMovie(true);$('render-preview').onclick=()=>renderMovie(false);

$('script-build').onclick=()=>{try{const next=scriptPlan($('script-text').value,assets,Number($('seconds').value));checkpoint();plan=next;draw();document.querySelector('.timeline-panel').open=true;$('script-status').textContent=`已生成 ${plan.clips.length} 个片段，请预览并检查画面与文案是否对应。`;status('文案分镜已生成，可继续调整。')}catch(e){$('script-status').textContent=e.message}};
$('script-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>100000)throw Error('脚本文件需小于 100KB');const text=await f.text();if(text.length>22000)throw Error('脚本最多 22000 字符');$('script-text').value=text;if(plan.clips.length)persist();$('script-status').textContent='文案已导入。点击生成可编辑分镜。'}catch(e){$('script-status').textContent=e.message}finally{e.target.value=''}};
$('api-test').onclick=async()=>{try{if(!$('api').value||!$('token').value)throw Error('请先填写后端地址和访问令牌');const base=new URL($('api').value);if(base.protocol!=='https:'&&!['localhost','127.0.0.1'].includes(base.hostname))throw Error('公开后端必须使用 HTTPS');$('api-test').disabled=true;const r=await fetch(base.origin+'/api/health',{headers:{Authorization:'Bearer '+$('token').value},signal:AbortSignal.timeout(10000)});const data=await r.json();if(!r.ok)throw Error(data.error||'连接失败');const multi=showHealth(data);$('api-state').textContent='零费用模式：当前网页不调用远程模型。'+(!multi?'后端已连接，但版本较旧；请更新 server/api.py 后使用多服务商。':data.model_configured?'后端连接成功。服务商配置已读取，远程模型仍保持关闭。':'后端连接成功，服务商尚未配置；零费用本地功能可以继续使用。')}catch(e){$('api-state').textContent='连接未成功：'+e.message+'。公开网页需使用 HTTPS 后端，并设置匹配的 ALLOWED_ORIGIN。'}finally{$('api-test').disabled=false}};

function stopTimelinePreview(){
 const video=$('preview');video.pause();video.style.transform='';video.style.opacity='';previewVisual=null;previewEnd=null;$('previewcaption').textContent='';
 if(!previewing)return;previewing=false;previewRun++;$('preview').pause();previewEnd=null;$('previewcaption').textContent='';$('preview-all').textContent='预览再创作时间线';$('preview-state').textContent='已停止预览';
}
$('preview-all').onclick=async()=>{
 if(previewing){stopTimelinePreview();return}
 try{
  const clips=structuredClone(current().clips),run=++previewRun;previewing=true;previewEnd=null;$('preview-all').textContent='停止预览';
  const v=$('preview');v.controls=false;$('preview-label').textContent='再创作预览 · 按新时间线播放（非原片）';v.pause();$('export-result').querySelector('video').pause();
  for(let i=0;i<clips.length;i++){
   if(run!==previewRun)return;const c=clips[i];v.pause();
   if(v.src!==assets[c.asset].url){const ready=waitEvent(v,'loadeddata');v.src=assets[c.asset].url;await ready}
   if(run!==previewRun)return;
   if(Math.abs(v.currentTime-c.start)>.01){const seek=waitEvent(v,'seeked');v.currentTime=c.start;await seek}
   if(run!==previewRun)return;
   previewVisual=c;$('previewcaption').textContent=c.caption;$('preview-state').textContent=`再创作 ${i+1}/${clips.length} 段 · 成片共 ${clips.reduce((n,c)=>n+c.end-c.start,0).toFixed(1)} 秒 · ${assets[c.asset].name}`;
   await v.play();await new Promise((resolve,reject)=>{const started=performance.now();const timer=setInterval(()=>{if(run!==previewRun||v.ended||v.currentTime>=c.end-.025){clearInterval(timer);resolve()}else if(performance.now()-started>(c.end-c.start+15)*1000){clearInterval(timer);reject(Error('播放停滞，请重试'))}},25)});
  }
  if(run===previewRun){stopTimelinePreview();$('preview-state').textContent='整条时间线预览完成。画面和字幕已按镜头顺序播放。'}
 }catch(e){stopTimelinePreview();$('preview-state').textContent=e.message}
};
document.querySelectorAll('[data-pane]').forEach(btn=>btn.addEventListener('click',stopTimelinePreview));
window.addEventListener('hashchange',stopTimelinePreview);

$('preview').addEventListener('timeupdate',()=>{if(!previewVisual)return;const v=$('preview'),c=previewVisual,state=visualEffect(c.effect,Math.max(0,v.currentTime-c.start),c.end-c.start);v.style.transform=`scale(${state.scale})`;v.style.opacity=state.alpha});
async function buildCreative(){
 let states;try{if(busy)throw Error('请等待当前导出或导入完成');if(!assets.length)throw Error('请先导入素材');stopTimelinePreview();const skill=getPresetSkill();const options={style:$('creative-style').value,topic:$('creative-topic').value,kind:$('creative-kind').value,mode:$('creative-mode').value,target:Number($('creative-seconds').value),referenceStyle};if(!Number.isFinite(options.target)||options.target<3||options.target>60)throw Error('目标时长需为 3–60 秒');let result,qualityWarning='';
 if($('creative-quality').checked){busy=true;states=new Map([...document.querySelectorAll('button,input,select,textarea')].map(e=>[e,e.disabled]));states.forEach((_,e)=>e.disabled=true);$('quality-cancel').hidden=false;$('quality-cancel').disabled=false;qualityAbort=new AbortController();try{let analyses=assets.map(a=>qualityCache.get(a.url));if(analyses.some(a=>!a)){analyses=await scanQuality(assets,{signal:qualityAbort.signal,onProgress:(n,total,i)=>{const text=`正在本地检查画面 ${n}/${total}：${assets[i].name}。不上传素材，不调用模型。`;$('creative-status').textContent=text;status(text)}});analyses.forEach((a,i)=>qualityCache.set(assets[i].url,a))}result=qualityPlan(assets,analyses,options)}catch(e){if(qualityAbort.signal.aborted)throw e;qualityWarning='画面优选未完成（'+e.message+'），已生成规则初稿。';result=creativePlan(assets,options)};
 }else result=creativePlan(assets,options);
 result=applyRecipeCaptions(result,skill);checkpoint();plan={clips:result.clips,referenceStyle:result.referenceStyle,skill:result.skill};$('creative-source').textContent=attribution(result.referenceStyle);$('script-text').value=result.copy;$('coach-goal').value=$('creative-kind').value;draw();document.querySelector('.timeline-panel').open=true;$('quality-results').replaceChildren();if(result.quality){for(const q of result.quality){const row=document.createElement('p');row.textContent=`${assets[q.asset].name} · ${q.start.toFixed(2)}–${q.end.toFixed(2)} 秒｜画面评分 ${Math.round(q.score*100)}/100｜依据 ${q.sampleTime.toFixed(2)} 秒采样。${q.flags.join('；')}`;$('quality-results').append(row)}}
 $('creative-status').textContent=qualityWarning+`已生成${result.style}：${result.clips.length} 段 / ${result.actual.toFixed(1)} 秒。${result.truncated?'选取区间不足目标时长，已缩短；可关闭画面优选使用更多原素材。':''}${result.quality?'按亮度、对比度、边缘细节优选，不代表语义精彩度。':''}文案未核对画面，请修改后预览。`;status(qualityWarning+`已用你的素材生成 ${result.clips.length} 段 / ${result.actual.toFixed(1)} 秒初稿。${remixReport(plan,assets).summary}预览后可查看原片时间对照；预览后点击“下载 MP4 成片”。`);return true;
 }catch(e){$('creative-status').textContent=e.message;status('未生成新初稿：'+e.message);return false}finally{if(states){busy=false;qualityAbort=null;$('quality-cancel').hidden=true;states.forEach((disabled,e)=>e.disabled=disabled)}}
}
$('quality-cancel').onclick=()=>qualityAbort?.abort();
$('creative-build').onclick=buildCreative;
$('creative-export').onclick=async()=>{if(await buildCreative())$('export').click()};

document.addEventListener('stop-preview',stopTimelinePreview);

function setReferenceStyle(profile){referenceStyle=validateStyleProfile(profile);const option=$('creative-style').querySelector('option[value="reference"]');option.disabled=false;option.textContent=profile.creator+' · 参考节奏';$('creative-style').value='reference'}
document.addEventListener('reference-style',e=>{try{setReferenceStyle(e.detail);$('creative-source').textContent=attribution(referenceStyle)+' 点击生成创意初稿后应用。';$('creative-status').textContent='参考节奏已载入，现有时间线尚未改变。';$('tab-edit').click();$('creative-build').focus()}catch(e){status(e.message)}});

export async function localCreativeTask(run){
 if(busy)throw Error('请等待当前操作完成');if(!assets.length)throw Error('请先导入素材');const target=Number($('creative-seconds').value);if(!Number.isFinite(target)||target<3||target>60)throw Error('目标时长需为 3–60 秒');busy=true;stopTimelinePreview();const states=new Map([...document.querySelectorAll('button,input,select,textarea')].map(e=>[e,e.disabled]));states.forEach((_,e)=>e.disabled=true);
 try{const {captureEvidence}=await import('./capture-frames.js');const frames=await captureEvidence(assets,(n,total)=>{$('creative-status').textContent=`准备本地视觉证据 ${n}/${total}…`});$('creative-status').textContent='本地视觉模型正在分析抽帧，可能需要数分钟；未调用云模型。';const result=await run({assets:assets.map(({name,duration})=>({name,duration})),frames,target,topic:$('creative-topic').value});validate(result,assets);if(result.skill)validateProvenance(result.skill);checkpoint();plan={clips:structuredClone(result.clips),skill:result.skill};draw();$('script-text').value=result.clips.map(c=>c.caption).join('\n');persist();document.querySelector('.timeline-panel').open=true;$('quality-results').replaceChildren();for(const c of result.clips){const row=document.createElement('p');row.textContent=`${assets[c.asset].name} ${c.start.toFixed(2)}–${c.end.toFixed(2)} 秒；引用 ${c.evidenceTime.toFixed(2)} 秒抽帧`;$('quality-results').append(row)}$('creative-status').textContent=`本地视觉方案已生成（${result.model}），请核对镜头与建议文案。`;return result;
 }finally{busy=false;states.forEach((disabled,e)=>e.disabled=disabled)}
}

export async function applyEditingSkill(input){
 if(busy)throw Error('请等待当前导入或导出完成');const skill=validateSkill(input);if(!skill.recipe)throw Error('这份 Skill 只有文字指导，需要本地 AI 解读');const r=skill.recipe;setActiveSkill(skill,'preset');for(const [key,id] of [['style','creative-style'],['kind','creative-kind'],['target','creative-seconds'],['topic','creative-topic'],['ratio','ratio']])if(r[key]!==undefined)$(id).value=r[key];$('tab-edit').click();return buildCreative();
}
